from collections import Counter
def transform(g):
    g=[r[:] for r in g]
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    acc=set(Counter(v for r in g for v in r))- {bg}
    # reference: a full accent row
    ref=None
    for row in g:
        if all(v in acc for v in row): ref=row; break
    for row in g:
        if all(v in acc for v in row) or not any(v in acc for v in row): continue
        for c,v in enumerate(row):
            if v!=ref[c]: row[c]=1
    return g
