prog='''from collections import Counter

def transform(grid):
    """Two mechanisms:
    A) A row whose accent cells form a contiguous prefix of a full accent
       reference row gets its trailing missing cells filled with 1
       (demo 1: 27 accent + 1 background -> last cell becomes 1).
    B) A later row that repeats an earlier row except at a few cells, where
       the later row has background and the earlier has accent, gets those
       divergent cells set to 1 (demo 2: repeated copy blocks).
    """
    g = [row[:] for row in grid]
    W = len(g[0])
    counts = Counter(v for row in g for v in row)
    bg = counts.most_common(1)[0][0]
    accents = set(counts) - {bg}

    def is_full(row):
        return all(v in accents for v in row)

    # Rule B: repeated-copy divergence
    for i, row in enumerate(g):
        if is_full(row):
            continue
        best = None
        for j in range(i):
            o = g[j]
            diffs = [c for c in range(W) if row[c] != o[c]]
            if not diffs or len(diffs) > 4:
                continue
            if all(row[c] == bg and o[c] in accents for c in diffs):
                if best is None or len(diffs) < len(best[1]):
                    best = (o, diffs)
        if best:
            for c in best[1]:
                row[c] = 1

    # Rule A: trailing gap after an accent prefix, vs a full accent row
    ref = next((r for r in g if is_full(r)), None)
    if ref is not None:
        for row in g:
            if is_full(row) or not any(v in accents for v in row):
                continue
            k = 0
            while k < W and row[k] in accents:
                k += 1
            if 0 < k < W and all(row[c] == bg for c in range(k, W)):
                for c in range(k, W):
                    row[c] = 1
    return g
'''
